/// 辺コストが0または1のグラフの、startから各頂点への最短距離を返す。
/// startと各辺の行き先はgraphの有効な頂点番号であることを前提とし、入力検証は行わない。
/// 到達不能な頂点の距離はUINF（(1_usize << 61) - 1）となる。
pub fn zero_one_bfs(graph: &Vec<Vec<(usize, usize)>>, start: usize) -> Vec<usize> {
    let n = graph.len();
    let mut dists = vec![UINF; n];
    let mut deque = VecDeque::<(usize, usize)>::with_capacity(n);

    dists[start] = 0;
    deque.push_front((start, 0));

    while let Some((v, d)) = deque.pop_front() {
        continueif!(d != dists[v]);

        for &(to, cost) in &graph[v] {
            let nextdist = d + cost;
            // 同距離を再投入すると、コスト0の閉路でキューが空にならない。
            continueif!(nextdist >= dists[to]);
            dists[to] = nextdist;

            if cost == 0 {
                deque.push_front((to, nextdist));
            } else {
                deque.push_back((to, nextdist));
            }
        }
    }
    return dists;
}
